              fl_value fl_t611 = fl_nothing(); /* «хвост» */
              FL_TRY(fl_b_hvost(ctx, fl_t610, &fl_t611, error));
              fl_value fl_t612 = fl_nothing();
              FL_TRY(kompilyator_flang_dlina_do_zakrytiya(ctx, fl_t611, fl_number(0.0), &fl_t612, error));
