/* Тело «Все случаи тотальны»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_vse_sluchai_totalny_body(fl_ctx *ctx, fl_value tegi, fl_value hod, fl_value *result, fl_error *error) {
  for (;;) {
    FL_TRY(fl_tick(ctx, "Все случаи тотальны", error));
    if (fl_chain_empty(tegi)) {
      *result = fl_flag(true);
      return FL_OK;
    } else if (fl_chain_cons(tegi)) {
      const fl_value golova = fl_chain_head(tegi); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(tegi); /* хвост «хвост» */
      fl_value fl_t8553 = fl_nothing();
      FL_TRY(fl_field_get(ctx, hod, "функции", &fl_t8553, error));
      fl_value fl_t8554 = fl_nothing();
      FL_TRY(kompilyator_flang_funkciya_totalna(ctx, fl_t8553, golova, &fl_t8554, error));
      bool fl_t8555 = false;
      FL_TRY(fl_cond(ctx, fl_t8554, &fl_t8555, error));
      if (fl_t8555) {
        const fl_value fl_t8556 = hod;
        tegi = hvost;
        hod = fl_t8556;
        continue;
      } else {
        *result = fl_flag(false);
        return FL_OK;
      }
    } else {
      return fl_match_fail(ctx, tegi, error);
    }
  }
}

